package net.rafa.rustcraft.damage;

import net.minecraft.entity.damage.DamageSource;
import net.minecraft.entity.damage.DamageType;
import net.minecraft.registry.Registerable;
import net.minecraft.registry.RegistryKey;
import net.minecraft.registry.RegistryKeys;
import net.minecraft.util.Identifier;
import net.minecraft.world.World;
import net.rafa.rustcraft.RustCraft;

/**
 * Damage types of the mod. Damage types are data: their JSON is generated by
 * {@code ModDynamicRegistryProvider} from {@link #bootstrap}, and their tags by {@code ModDamageTypeTagProvider}.
 * Death messages are {@code death.attack.rustcraft.<name>} in the lang provider.
 */
public final class ModDamageTypes {
    private ModDamageTypes() {}

    /** Thirst at 0. Works like vanilla starvation. */
    public static final RegistryKey<DamageType> DEHYDRATION = of("dehydration");

    /** Called by datagen to write the damage type JSON. */
    public static void bootstrap(Registerable<DamageType> context) {
        // Message id "rustcraft.dehydration" → death.attack.rustcraft.dehydration. No exhaustion, like starvation.
        context.register(DEHYDRATION, new DamageType(RustCraft.MOD_ID + ".dehydration", 0.0f));
    }

    /** A damage source of the given type, for {@code entity.damage(...)}. */
    public static DamageSource source(World world, RegistryKey<DamageType> type) {
        return new DamageSource(world.getRegistryManager().get(RegistryKeys.DAMAGE_TYPE).entryOf(type));
    }

    private static RegistryKey<DamageType> of(String name) {
        return RegistryKey.of(RegistryKeys.DAMAGE_TYPE, Identifier.of(RustCraft.MOD_ID, name));
    }
}
